const row = $input.first().json;

const patient_id = String(row.patient_id || '').trim();
const clinician_email = String(row.clinician_email || '').trim();
const document_type = String(row.document_type || 'lab_report').trim();
const priority = String(row.priority || 'normal').trim();
const notes = String(row.notes || '').trim();

if (!patient_id) throw new Error('Missing patient_id in sheet row');
if (!clinician_email) throw new Error('Missing clinician_email in sheet row');

const validTypes = ['lab_report', 'discharge_summary', 'radiology', 'pathology'];
const docType = validTypes.includes(document_type) ? document_type : 'lab_report';

// Pass ALL sheet columns through — lab values included
return [{ json: {
  patient_id,
  clinician_email,
  document_type: docType,
  priority,
  notes,
  received_at: new Date().toISOString(),
  file_name: 'document.pdf',
  // Lab value columns — passed as-is from sheet
  hba1c: String(row.hba1c || '').trim(),
  ldl: String(row.ldl || '').trim(),
  bmi: String(row.bmi || '').trim(),
  blood_pressure: String(row.blood_pressure || '').trim(),
  medications: String(row.medications || '').trim(),
  diagnoses: String(row.diagnoses || '').trim(),
  hdl: String(row.hdl || '').trim(),
  fasting_glucose: String(row.fasting_glucose || '').trim(),
  age: String(row.age || '').trim(),
  gender: String(row.gender || '').trim()
}}];

const raw = $input.first().json;
const meta = $('Input Validator').first().json;
const extracted = raw.extracted || raw.data || raw.result || {};

// NO fallbacks — use exactly what Nutrient extracted
const labValues = extracted.lab_values;
const medications = extracted.medications;
const diagnoses = extracted.diagnoses;

if (!labValues) throw new Error('Format Extraction: lab_values missing from Nutrient output');
if (!medications) throw new Error('Format Extraction: medications missing from Nutrient output');
if (!diagnoses) throw new Error('Format Extraction: diagnoses missing from Nutrient output');

const confidence = extracted.confidence_scores || {};
const clinicalFlags = extracted.clinical_flags || [];

const lowConfidenceFields = [];
for (const [field, score] of Object.entries(confidence)) {
  if (typeof score === 'number' && score < 0.80) {
    lowConfidenceFields.push({ field, score: Math.round(score * 100) + '%' });
  }
}

const scores = Object.values(confidence).filter(v => typeof v === 'number');
const avgConfidence = scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : 0.0;

// requires_review if avg confidence low, too many low-confidence fields, OR clinical flags present
const requiresReview = avgConfidence < 0.80 || lowConfidenceFields.length > 2 || clinicalFlags.length > 0;

return [{ json: {
  patient_id: meta.patient_id,
  clinician_email: meta.clinician_email,
  document_type: meta.document_type,
  priority: meta.priority,
  received_at: meta.received_at,
  file_name: meta.file_name,
  lab_values: labValues,
  medications,
  diagnoses,
  physician_notes: extracted.physician_notes || '',
  patient_age: (extracted.patient_demographics || {}).age || 'unknown',
  report_date: (extracted.dates || {}).report_date || new Date().toISOString().split('T')[0],
  extraction_confidence: Math.round(avgConfidence * 100) / 100,
  low_confidence_fields: lowConfidenceFields,
  clinical_flags: clinicalFlags,
  requires_review: requiresReview,
  agent_context: JSON.stringify({ lab_values: labValues, medications, diagnoses, document_type: meta.document_type }, null, 2)
}}];

