const agentOut = $input.first().json;
const ctx = $('Format Extraction Output').first().json;

// Agent score lives under output.confidence_score (structured parser output)
const agentScore = (agentOut.output || {}).confidence_score || agentOut.confidence_score;
const extractionScore = ctx.extraction_confidence || 0;

if (agentScore === undefined || agentScore === null) {
  throw new Error('No confidence_score in agent output — check Clinical Brief Parser schema');
}

const combinedConfidence = Math.round((agentScore + extractionScore) / 2 * 100) / 100;

const clinicalFlags = ctx.clinical_flags || [];
const requiresReview = (agentOut.output || {}).requires_review || ctx.requires_review || combinedConfidence < 0.80 || clinicalFlags.length > 0;

return [{ json: {
  ...agentOut,
  output: agentOut.output || {},
  patient_id: ctx.patient_id,
  clinician_email: ctx.clinician_email,
  document_type: ctx.document_type,
  report_date: ctx.report_date,
  file_name: ctx.file_name,
  extraction_confidence: extractionScore,
  lab_values: ctx.lab_values,
  medications: ctx.medications,
  diagnoses: ctx.diagnoses,
  clinical_flags: clinicalFlags,
  confidence_score: combinedConfidence,
  requires_review: requiresReview,
  low_confidence_fields: [...((agentOut.output || {}).low_confidence_fields || []), ...(ctx.low_confidence_fields || [])],
  generated_at: new Date().toISOString()
}}];

const d = $input.first().json;
// Structured audit record — visible in n8n execution log
const auditRecord = {
  patient_id: d.patient_id,
  document_type: d.document_type,
  confidence_score: d.confidence_score,
  extraction_confidence: d.extraction_confidence,
  requires_review: d.requires_review,
  clinical_flags: d.clinical_flags || [],
  low_confidence_fields: d.low_confidence_fields || [],
  risk_level: (d.output || {}).risk_level || 'unknown',
  generated_at: d.generated_at,
  routed_to: d.requires_review ? 'human_review' : 'foxit_esign'
};
console.log('CLINICALBRIEF_AUDIT:', JSON.stringify(auditRecord));
return [{ json: { ...d, audit_logged: true, audit_record: auditRecord } }];

const row = $('Input Validator').first().json;

const required = ['hba1c', 'ldl', 'diagnoses'];
for (const field of required) {
  if (!row[field] || String(row[field]).trim() === '') {
    throw new Error(`Missing required field: ${field}. Please fill in all lab value columns in the sheet.`);
  }
}

const hba1c = String(row.hba1c).trim();
const ldl = String(row.ldl).trim();
const bmi = String(row.bmi || 'not provided').trim();
const blood_pressure = String(row.blood_pressure || 'not provided').trim();
const fasting_glucose = String(row.fasting_glucose || 'not provided').trim();
const hdl = String(row.hdl || 'not provided').trim();

const medicationsRaw = String(row.medications || '').trim();
const medications = medicationsRaw ? medicationsRaw.split(',').map(m => m.trim()).filter(Boolean) : [];

const diagnosesRaw = String(row.diagnoses || '').trim();
const diagnoses = diagnosesRaw ? diagnosesRaw.split(',').map(d => d.trim()).filter(Boolean) : [];

const isVague = (s) => ['unknown','possible','not provided','unclear','unsure'].some(w => s.toLowerCase().includes(w));

// Parse numeric values for threshold checks
const hba1c_val = parseFloat(hba1c);
const ldl_val = parseFloat(ldl);
const bmi_val = parseFloat(bmi);
const systolic = parseFloat((blood_pressure.split('/')[0] || '0'));

// Clinical threshold flags — extreme values require human review
const clinicalFlags = [];
if (!isNaN(hba1c_val) && hba1c_val > 10.0) clinicalFlags.push(`HbA1c critically high: ${hba1c} (>10% requires urgent review)`);
if (!isNaN(ldl_val) && ldl_val > 190) clinicalFlags.push(`LDL critically elevated: ${ldl} (>190 mg/dL requires urgent review)`);
if (!isNaN(bmi_val) && bmi_val > 40) clinicalFlags.push(`BMI severely obese: ${bmi} (>40 requires specialist review)`);
if (!isNaN(systolic) && systolic > 160) clinicalFlags.push(`Blood pressure hypertensive crisis: ${blood_pressure} (>160 systolic requires urgent review)`);

const confidence_scores = {
  hba1c: !isNaN(hba1c_val) && hba1c_val > 10.0 ? 0.60 : 0.98,
  ldl_cholesterol: !isNaN(ldl_val) && ldl_val > 190 ? 0.60 : 0.96,
  bmi: bmi === 'not provided' ? 0.50 : (!isNaN(bmi_val) && bmi_val > 40 ? 0.62 : 0.95),
  blood_pressure: blood_pressure === 'not provided' ? 0.50 : (!isNaN(systolic) && systolic > 160 ? 0.62 : 0.94),
  medications: medications.length > 0 && !isVague(medicationsRaw) ? 0.92 : 0.40,
  diagnoses: diagnoses.length > 0 && !isVague(diagnosesRaw) ? 0.91 : 0.42
};

return [{ json: {
  extracted: {
    lab_values: { hba1c, ldl_cholesterol: ldl, bmi, blood_pressure, fasting_glucose, hdl_cholesterol: hdl },
    medications,
    diagnoses,
    patient_demographics: { age: String(row.age || 'unknown').trim(), gender: String(row.gender || 'unknown').trim() },
    dates: { report_date: new Date().toISOString().split('T')[0] },
    physician_notes: String(row.notes || '').trim(),
    confidence_scores,
    clinical_flags: clinicalFlags
  },
  source: 'google_sheets_patient_intake',
  patient_id: row.patient_id,
  document_type: row.document_type
}}];

const ctx = $('Format Extraction Output').first().json;
const serpNode = 'SerpApi — Clinical Search';
let evidence = 'No search results available';
try {
  const serpResults = $('SerpApi — Clinical Search').first().json;
  evidence = (serpResults.organic_results || []).slice(0,3)
    .map((r, i) => (i+1) + '. ' + r.title + ' — ' + (r.snippet || '').substring(0,150) + (r.link ? ' [' + r.link + ']' : ''))
    .join('\n');
} catch(e) { evidence = 'Search unavailable'; }

const built_prompt = 'Patient document data:\n' + ctx.agent_context +
  '\n\nPatient ID: ' + ctx.patient_id +
  '\nDocument type: ' + ctx.document_type +
  '\nReport date: ' + ctx.report_date +
  '\n\nReal-time clinical evidence from PubMed (SerpApi):\n' + evidence +
  '\n\nTasks:\n1. Use retrieve_clinical_protocols tool to get matching protocol documents from KB\n2. Generate structured clinical brief using patient data AND the PubMed evidence above\n3. Cite the PubMed sources in evidence_sources with titles and URLs\n\nRules: Always cite sources. Reference actual lab values in summary. Output valid JSON.';

return [{ json: { ...ctx, built_prompt } }];
